class MemberAvatar extends StatelessWidget { const MemberAvatar({super.key, required this.member, required this.settings, this.size=DesignTokens.avatarSize}); final FamilyMember member; final FamilySettings settings; final double size; @override Widget build(BuildContext context){ final gender=(member.data['gender']??'other').toString(); final color=Color(int.parse((settings.genderColors[gender]??'#8E44AD').substring(1), radix:16)+0xFF000000); final dod=(member.data['dod']??'').toString().isNotEmpty; final radius=settings.photoShape=='circle'?size:settings.photoShape=='square'?0.0:DesignTokens.radiusMedium; Widget img=Image.network((member.data['photo']??'https://i.pravatar.cc/300?u=${member.id}').toString(), fit:BoxFit.cover, color: dod?Colors.grey:null, colorBlendMode: dod?BlendMode.saturation:null); if(settings.photoShape=='hexagon') img=ClipPath(clipper:_Hex(), child: img); else img=ClipRRect(borderRadius: BorderRadius.circular(radius), child: img); return Container(width:size,height:size, padding: const EdgeInsets.all(DesignTokens.avatarBorderWidth), decoration: BoxDecoration(shape: settings.photoShape=='circle'?BoxShape.circle:BoxShape.rectangle, borderRadius: settings.photoShape=='circle'?null:BorderRadius.circular(radius), border: Border.all(color: dod?Colors.grey:color, width: dod?1.5:DesignTokens.avatarBorderWidth)), child: img); }} class _Hex extends CustomClipper<Path>{ @override Path getClip(Size s)=>Path()..moveTo(s.width*.5,0)..lineTo(s.width,s.height*.25)..lineTo(s.width,s.height*.75)..lineTo(s.width*.5,s.height)..lineTo(0,s.height*.75)..lineTo(0,s.height*.25)..close(); @override bool shouldReclip(c)=>false; }
